        } else {
            step_x = 1;
            side_dist_x = (map_x as f32 + 1.0 - pos_x) * delta_dist_x;
        }

        if ray_dir_y < 0.0 {
            step_y = -1;
            side_dist_y = (pos_y - map_y as f32) * delta_dist_y;
        } else {
