pub fn get_wall_texture_ptr() -> *mut u8 {
    #[allow(static_mut_refs)]
    unsafe {
        if let Some(ref mut v) = WALL_TEX_VEC {
            v.as_mut_ptr()
        } else {
            WALL_TEX_BUF.as_mut_ptr()
